func sortList(head *ListNode) *ListNode {
	if head == nil || head.Next == nil {
		return head // termination.
	}
	// cut the LinkedList at the mid index.
	slow, fast := head, head.Next
	for fast != nil && fast.Next != nil {
		fast = fast.Next.Next
		slow = slow.Next
	}
	mid := slow.Next
	slow.Next = nil // save and cut.
	// recursive for cutting.
	left, right := sortList(head), sortList(mid)
	// merge `left` and `right` linked list and return it.
	h := &ListNode{}
	res := h
	for left != nil && right != nil {
		if left.Val < right.Val {
			h.Next = left
			left = left.Next
		} else {
			h.Next = right
			right = right.Next
		}
		h = h.Next
	}
	if left != nil {
		h.Next = left
	} else {
		h.Next = right
	}
	return res.Next
}

func sortList(head *ListNode) *ListNode {
	h, length, intv := head, 0, 1
	for h != nil {
		h = h.Next
		length++
	}
	res := &ListNode{}
	res.Next = head
	// merge the list in different intv.
	for intv < length {
		pre, h := res, res.Next
		for h != nil {
			// get the two merge head `h1`, `h2`
			h1, i := h, intv
			for i > 0 && h != nil {
				h = h.Next
				i--
			}
			if i > 0 {
				break // no need to merge because the `h2` is None.
			}
			h2, i := h, intv
			for i > 0 && h != nil {
				h = h.Next
				i--
			}
			c1, c2 := intv, intv-i // the `c2`: length of `h2` can be smaller than the `intv`.
			// merge the `h1` and `h2`.
			for c1 > 0 && c2 > 0 {
				if h1.Val < h2.Val {
					pre.Next = h1
					h1 = h1.Next
					c1--
				} else {
					pre.Next = h2
					h2 = h2.Next
					c2--
				}
				pre = pre.Next
			}
			if c1 > 0 {
				pre.Next = h1
			} else {
				pre.Next = h2
			}
			for c1 > 0 || c2 > 0 {
				pre = pre.Next
				c1--
				c2--
			}
			pre.Next = h
		}
		intv *= 2
	}
	return res.Next
}
